/**
 * Handles the initial login with username and password.
 * If successful, it triggers the 2FA email sending process.
 * 
 * @param {string} username 
 * @param {string} password 
 * @returns {Promise<Object>} A promise that resolves with a session token or rejects with an error.
 */
async function loginWith2FA(username, password) {
    try {
        // Step 1: Authenticate with username and password
        const authResponse = await fetch('/api/auth/login', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/json'
            },
            body: JSON.stringify({ username, password })
        });

        if (!authResponse.ok) {
            const errorData = await authResponse.json();
            throw new Error(errorData.message || 'Authentication failed');
        }

        const data = await authResponse.json();

        // Check if 2FA is required for this user
        if (data.requires2FA) {
            // Step 2: Send 2FA code to user's email
            await send2FACode(data.userId);
            return { status: '2FA_REQUIRED', userId: data.userId };
        } else {
            // No 2FA required, return session token
            return { status: 'SUCCESS', token: data.token };
        }

    } catch (error) {
        console.error('Login error:', error);
        throw error;
    }
}

